208 // -------------------------------------------------------------------------------
213 inline unsigned int integer_pow(unsigned int base, unsigned int power) {
214     unsigned int res = 1;
215     for (unsigned int i = 0; i < power; ++i) {
216         res *= base;
217     }
218 
219     return res;
220 }
